((SELECT id FROM vocab_words WHERE lower(headword)=lower('experimentally')), 'Researchers have demonstrated that the theory is experimentally verified through multiple tests.', '研究人员通过多次测试证明了该理论的实验结果可验证。', 'experimentally verified', 'science_tech', 0),
