((SELECT id FROM vocab_words WHERE lower(headword)=lower('envisage')), 'Many companies envisage a future where remote work becomes the norm.', '许多公司设想未来远程工作将成为常态。', 'envisage a future', 'work', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('envisage')), 'Researchers envisage significant changes in technology within the next decade.', '研究人员设想在未来十年内技术将发生重大变化。', 'envisage significant changes', 'science_tech', 1),
