((SELECT id FROM vocab_words WHERE lower(headword)=lower('mitten')), 'During winter, she always wears her warm mittens when going outside.', '冬天，她外出时总是戴着温暖的连指手套。', 'winter mitten', 'daily_life', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('mitten')), 'In the craft fair, handmade knitted mittens were very popular among the visitors.', '在手工艺品博览会上，手工编织的连指手套在游客中十分受欢迎。', 'knitted mitten', 'culture', 1),
