((SELECT id FROM vocab_words WHERE lower(headword)=lower('amends')), 'He decided to make amends after realizing his mistake hurt her feelings.', '他意识到自己的错误伤害了她的感情后，决定赔罪。', 'make amends', 'daily_life', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('amends')), 'The company offered amends to the affected customers after the service outage incident.', '在服务中断事件后，公司向受影响的客户提供了补偿。', 'offer amends', 'work', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('amends')), 'Researchers often seek amends for past wrongdoings in their studies to maintain integrity.', '研究人员通常寻求补偿以纠正其研究中的过失，以保持诚信。', 'seek amends', 'academic', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('ramble')), 'Friends often ramble on about their weekend adventures, sharing amusing stories and experiences.', '朋友们常常闲聊他们的周末冒险，分享有趣的故事和经历。', 'ramble on', 'daily_life', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('ramble')), 'Students tend to ramble through their presentations, losing focus on the main topic.', '学生们往往在演讲中漫谈，使得重点不集中。', 'ramble through', 'education', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('ramble')), 'During the interview, the author rambled about his inspiration for the novel and its themes.', '在采访中，作者漫谈了他对小说及其主题的灵感。', 'ramble about', 'culture', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('centralize')), 'Organizations often centralize resources to improve efficiency and reduce costs.', '为了提高效率和降低成本，组织通常会集中资源。', 'centralize resources', 'work', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('centralize')), 'To enhance security, companies should centralize data management across all departments.', '为了增强安全性，公司应在所有部门集中数据管理。', 'centralize data management', 'science_tech', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('centralize')), 'Educators argue that schools must centralize decision-making to ensure consistent policies.', '教育工作者认为，学校必须集中决策以确保政策的一致性。', 'centralize decision-making', 'education', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('fastener')), 'Zippers are a common type of fastener used in clothing and bags.', '拉链是衣物和包袋中常用的一种紧固件。', 'zip fastener', 'daily_life', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('fastener')), 'Engineers focus on fastener design to enhance product safety and durability.', '工程师专注于紧固件设计，以提高产品的安全性和耐用性。', 'fastener design', 'science_tech', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('fastener')), 'In construction, metal fasteners are often preferred for their strength and reliability.', '在建筑中，金属紧固件因其强度和可靠性而受到青睐。', 'metal fasteners', 'work', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('woodpecker')), 'Numerous woodpecker species inhabit various forest ecosystems around the world.', '众多啄木鸟物种栖息在全球不同的森林生态系统中。', 'woodpecker species', 'science_tech', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('woodpecker')), 'Researchers documented the distinct woodpecker calls during their spring migration observations.', '研究人员在春季迁徙观察中记录了啄木鸟的独特叫声。', 'woodpecker calls', 'environment', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('woodpecker')), 'The study focused on the conservation of woodpecker habitat in urban areas.', '这项研究聚焦于城市地区啄木鸟栖息地的保护。', 'woodpecker habitat', 'academic', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('fro')), 'Children often run fro their parents when they are playing outside.', '孩子们在外面玩耍时常常向后跑开父母。', 'run fro', 'daily_life', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('fro')), 'The company had to back fro its earlier commitment due to financial issues.', '由于财务问题，该公司不得不撤回之前的承诺。', 'back fro', 'news', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('fro')), 'Research shows that the relationship between variables can shift from fro different contexts.', '研究表明，变量之间的关系可能因不同的背景而有所变化。', 'from fro', 'academic', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('taper')), 'As the storm approached, winds began to taper off by early evening.', '随着风暴逼近，风速在傍晚早些时候开始减弱。', 'taper off', 'news', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('taper')), 'After weeks of treatment, the dosage has started tapering off for better recovery.', '经过几周的治疗，药量已经开始逐渐减少以便更好地恢复。', 'tapering off', 'health', 1),
