((SELECT id FROM vocab_words WHERE lower(headword)=lower('axial')), 'Symmetry in organisms often exhibits axial symmetry, providing balance and functionality.', '生物体的对称性往往表现为轴向对称，提供平衡和功能性。', 'axial symmetry', 'science_tech', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('axial')), 'Engineers frequently analyze axial rotation in machinery to enhance efficiency and performance.', '工程师经常分析机械的轴向旋转，以提高效率和性能。', 'axial rotation', 'work', 1),
