((SELECT id FROM vocab_words WHERE lower(headword)=lower('automate')), 'Many companies aim to automate processes to enhance efficiency and reduce costs.', '许多公司旨在自动化流程，以提高效率并降低成本。', 'automate processes', 'work', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('automate')), 'Researchers are finding new ways to automate tasks that previously required significant manual effort.', '研究人员正在寻找新的方法来自动化以前需要大量人工的任务。', 'automate tasks', 'science_tech', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('automate')), 'Educators often seek to automate workflows in order to streamline administrative duties and focus on teaching.', '教育工作者通常寻求自动化工作流程，以简化行政职责并专注于教学。', 'automate workflows', 'education', 2),
