((SELECT id FROM vocab_words WHERE lower(headword)=lower('distil')), 'Artists often distil the essence of their experiences into their work for deeper connection.', '艺术家们常常将自己经历的精华提炼到作品中，以建立更深的联系。', 'distil essence', 'culture', 2),
