((SELECT id FROM vocab_words WHERE lower(headword)=lower('homely')), 'She wore a homely sweater that reminded everyone of their childhood.', '她穿着一件朴素的毛衣，让每个人想起了童年。', 'homely sweater', 'daily_life', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('homely')), 'Many people prefer homely decor that creates a warm and inviting atmosphere.', '许多人更喜欢朴素的装饰，营造温暖宜人的氛围。', 'homely decor', 'culture', 1),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('homely')), 'After a long day, nothing is more comforting than a homely meal at home.', '经过漫长的一天，家里的一顿简单饭菜是最舒适的。', 'homely meal', 'health', 2),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('wharf')), 'Developers have proposed new wharf facilities for the growing cargo traffic.', '开发商已提议为日益增长的货物交通建设新的码头设施。', 'wharf facilities', 'work', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('wharf')), 'Many locals gather at the fishing wharf to sell their fresh catch.', '许多当地人在渔码头聚集，出售他们的新鲜捕获。', 'fishing wharf', 'daily_life', 1),
