((SELECT id FROM vocab_words WHERE lower(headword)=lower('merciful')), 'The manager made a merciful decision to give the employee another chance after the mistake.', '经理做出了一个仁慈的决定，给了员工另一个机会，弥补错误。', 'merciful decision', 'work', 0),
((SELECT id FROM vocab_words WHERE lower(headword)=lower('merciful')), 'Many consider his donation a merciful act that helped the needy in the community.', '许多人认为他的捐款是一个仁慈的行为，帮助了社区中的贫困人群。', 'merciful act', 'culture', 1),
