((SELECT id FROM vocab_words WHERE lower(headword)=lower('intonation')), 'Teachers often emphasize intonation patterns to help students understand meaning in spoken language.', '教师经常强调语调模式，以帮助学生理解口语中的意义。', 'intonation patterns', 'education', 0),
